-- ============================================================================
-- Atlas-managed canonical schema for Raven (schema-as-code).
--
-- DO NOT EDIT BY HAND. Regenerate with:  make schema-inspect
--
-- This file is the declarative, version-controlled snapshot of the Postgres
-- schema, produced verbatim by `atlas schema inspect` against a database that
-- has had ALL goose migrations in migrations/ applied. It is the Dolt-like
-- artifact: `git diff` / `git blame` / branch / merge the schema shape here.
--
-- goose REMAINS the applier of record (Makefile `migrate-up`). Atlas does NOT
-- apply migrations at runtime; it only provides schema version-control review.
-- See docs/adr/0010-atlas-schema-version-control.md.
--
-- EXTENSIONS are owned by migrations/00001_extensions_and_types.sql, which runs:
--     CREATE EXTENSION "uuid-ossp";
--     CREATE EXTENSION "vector";   -- pgvector, enables vector(768) + HNSW below
--     CREATE EXTENSION "pg_trgm";
-- They are intentionally NOT re-emitted as executable DDL in this file: the
-- free-tier `atlas` binary rejects CREATE EXTENSION in a declarative schema
-- source ("extensions are available to logged-in users only"), and re-emitting
-- them would break `make schema-diff`. The pgvector round-trip is proven below
-- by the vector(768) columns and the `USING HNSW (... vector_cosine_ops)`
-- indexes, which Atlas inspected and reproduces faithfully. The Atlas dev-url
-- used by `make schema-inspect` / `make schema-diff` pre-installs these three
-- extensions (and the raven_app / raven_admin roles) so the schema materialises.
-- ============================================================================

-- Create enum type "org_status"
CREATE TYPE "org_status" AS ENUM ('active', 'suspended', 'deactivated');
-- Create enum type "user_status"
CREATE TYPE "user_status" AS ENUM ('active', 'disabled');
-- Create enum type "workspace_role"
CREATE TYPE "workspace_role" AS ENUM ('owner', 'admin', 'member', 'viewer');
-- Create enum type "kb_status"
CREATE TYPE "kb_status" AS ENUM ('active', 'archived', 'read_only_private', 'dmca_pending');
-- Create enum type "processing_status"
CREATE TYPE "processing_status" AS ENUM ('queued', 'crawling', 'parsing', 'chunking', 'embedding', 'ready', 'failed', 'reprocessing');
-- Create enum type "source_type"
CREATE TYPE "source_type" AS ENUM ('url', 'sitemap', 'rss_feed', 'web_page', 'web_site');
-- Create enum type "crawl_frequency"
CREATE TYPE "crawl_frequency" AS ENUM ('manual', 'daily', 'weekly', 'monthly');
-- Create enum type "chunk_type"
CREATE TYPE "chunk_type" AS ENUM ('text', 'table', 'image_caption', 'code');
-- Create enum type "llm_provider"
CREATE TYPE "llm_provider" AS ENUM ('openai', 'anthropic', 'cohere', 'google', 'azure_openai', 'custom', 'ollama');
-- Create enum type "provider_status"
CREATE TYPE "provider_status" AS ENUM ('active', 'revoked', 'expired');
-- Create enum type "api_key_status"
CREATE TYPE "api_key_status" AS ENUM ('active', 'revoked');
-- Create enum type "message_role"
CREATE TYPE "message_role" AS ENUM ('user', 'assistant', 'system');
-- Create enum type "routing_mode"
CREATE TYPE "routing_mode" AS ENUM ('static', 'column_based', 'auto');
-- Create enum type "connector_status"
CREATE TYPE "connector_status" AS ENUM ('active', 'paused', 'error', 'deleted');
-- Create enum type "sync_mode"
CREATE TYPE "sync_mode" AS ENUM ('full_refresh', 'incremental', 'cdc');
-- Create enum type "security_rule_type"
CREATE TYPE "security_rule_type" AS ENUM ('ip_allowlist', 'ip_denylist', 'geo_block', 'pattern_match', 'rate_override');
-- Create enum type "security_action"
CREATE TYPE "security_action" AS ENUM ('allow', 'block', 'throttle', 'log', 'alert');
-- Create enum type "webhook_status"
CREATE TYPE "webhook_status" AS ENUM ('active', 'paused', 'failed');
-- Create enum type "stranger_status"
CREATE TYPE "stranger_status" AS ENUM ('active', 'throttled', 'blocked', 'banned');
-- Create enum type "notification_type"
CREATE TYPE "notification_type" AS ENUM ('conversation_summary', 'admin_digest', 'custom');
-- Create enum type "notification_status"
CREATE TYPE "notification_status" AS ENUM ('pending', 'sent', 'failed');
-- Create enum type "voice_session_state"
CREATE TYPE "voice_session_state" AS ENUM ('created', 'active', 'ended');
-- Create enum type "voice_speaker"
CREATE TYPE "voice_speaker" AS ENUM ('agent', 'user');
-- Create enum type "whatsapp_call_direction"
CREATE TYPE "whatsapp_call_direction" AS ENUM ('inbound', 'outbound');
-- Create enum type "whatsapp_call_state"
CREATE TYPE "whatsapp_call_state" AS ENUM ('ringing', 'connected', 'ended');
-- Create enum type "kb_visibility"
CREATE TYPE "kb_visibility" AS ENUM ('private', 'public');
-- Create "goose_db_version" table
CREATE TABLE "goose_db_version" (
  "id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "version_id" bigint NOT NULL,
  "is_applied" boolean NOT NULL,
  "tstamp" timestamp NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);
-- Create "organizations" table
CREATE TABLE "organizations" (
  "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
  "name" character varying(255) NOT NULL,
  "slug" character varying(64) NOT NULL,
  "status" "org_status" NOT NULL DEFAULT 'active',
  "settings" jsonb NULL DEFAULT '{}',
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "takedown_strikes" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id"),
  CONSTRAINT "organizations_slug_key" UNIQUE ("slug"),
  CONSTRAINT "organizations_slug_format_check" CHECK ((slug)::text ~ '^[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?$'::text)
);
-- Create index "idx_organizations_slug" to table: "organizations"
CREATE INDEX "idx_organizations_slug" ON "organizations" ("slug");
-- Create index "idx_organizations_status" to table: "organizations"
CREATE INDEX "idx_organizations_status" ON "organizations" ("status");
-- Create "users" table
CREATE TABLE "users" (
  "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
  "org_id" uuid NULL,
  "email" character varying(255) NOT NULL,
  "display_name" character varying(255) NULL,
  "external_id" character varying(255) NULL,
  "status" "user_status" NOT NULL DEFAULT 'active',
  "last_login_at" timestamptz NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "auth_provider" text NOT NULL DEFAULT 'supertokens',
  PRIMARY KEY ("id"),
  CONSTRAINT "users_keycloak_sub_key" UNIQUE ("external_id"),
  CONSTRAINT "users_org_id_email_key" UNIQUE ("org_id", "email"),
  CONSTRAINT "users_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- Create index "idx_users_email" to table: "users"
CREATE INDEX "idx_users_email" ON "users" ("email");
-- Create index "idx_users_external_id" to table: "users"
CREATE UNIQUE INDEX "idx_users_external_id" ON "users" ("external_id") WHERE (external_id IS NOT NULL);
-- Create index "idx_users_org_id" to table: "users"
CREATE INDEX "idx_users_org_id" ON "users" ("org_id");
-- Create "account_purge_warnings" table
CREATE TABLE "account_purge_warnings" (
  "user_id" uuid NOT NULL,
  "warned_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("user_id"),
  CONSTRAINT "account_purge_warnings_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- Create "workspaces" table
CREATE TABLE "workspaces" (
  "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
  "org_id" uuid NOT NULL,
  "name" character varying(255) NOT NULL,
  "slug" character varying(100) NOT NULL,
  "settings" jsonb NULL DEFAULT '{}',
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "email_summaries_enabled" boolean NOT NULL DEFAULT false,
  PRIMARY KEY ("id"),
  CONSTRAINT "workspaces_org_id_slug_key" UNIQUE ("org_id", "slug"),
  CONSTRAINT "workspaces_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- Create index "idx_workspaces_org_id" to table: "workspaces"
CREATE INDEX "idx_workspaces_org_id" ON "workspaces" ("org_id");
-- Create "knowledge_bases" table
CREATE TABLE "knowledge_bases" (
  "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
  "org_id" uuid NOT NULL,
  "workspace_id" uuid NOT NULL,
  "name" character varying(255) NOT NULL,
  "slug" character varying(100) NOT NULL,
  "description" text NULL,
  "settings" jsonb NULL DEFAULT '{}',
  "status" "kb_status" NOT NULL DEFAULT 'active',
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "cache_enabled" boolean NOT NULL DEFAULT true,
  "cache_similarity_threshold" real NOT NULL DEFAULT 0.92,
  "visibility" "kb_visibility" NOT NULL DEFAULT 'private',
  "published_at" timestamptz NULL,
  "published_by_user_id" uuid NULL,
  "source_public_kb_id" uuid NULL,
  "imported_from_revision_at" timestamptz NULL,
  "last_modified_at" timestamptz NOT NULL DEFAULT now(),
  "license_spdx_id" text NULL,
  "import_count" integer NOT NULL DEFAULT 0,
  "preview_count" integer NOT NULL DEFAULT 0,
  "search_tsv" tsvector NULL GENERATED ALWAYS AS (setweight(to_tsvector('english'::regconfig, (COALESCE(name, ''::character varying))::text), 'A'::"char") || setweight(to_tsvector('english'::regconfig, COALESCE(description, ''::text)), 'B'::"char")) STORED,
  PRIMARY KEY ("id"),
  CONSTRAINT "knowledge_bases_workspace_id_slug_key" UNIQUE ("workspace_id", "slug"),
  CONSTRAINT "knowledge_bases_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "knowledge_bases_published_by_user_id_fkey" FOREIGN KEY ("published_by_user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  CONSTRAINT "knowledge_bases_source_public_kb_id_fkey" FOREIGN KEY ("source_public_kb_id") REFERENCES "knowledge_bases" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  CONSTRAINT "knowledge_bases_workspace_id_fkey" FOREIGN KEY ("workspace_id") REFERENCES "workspaces" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "knowledge_bases_cache_similarity_threshold_check" CHECK ((cache_similarity_threshold >= (0.80)::double precision) AND (cache_similarity_threshold <= (0.99)::double precision)),
  CONSTRAINT "knowledge_bases_public_requires_license" CHECK ((visibility = 'private'::kb_visibility) OR (license_spdx_id IS NOT NULL))
);
-- Create index "idx_kb_last_modified_at_public" to table: "knowledge_bases"
CREATE INDEX "idx_kb_last_modified_at_public" ON "knowledge_bases" ("last_modified_at" DESC) WHERE (visibility = 'public'::kb_visibility);
-- Create index "idx_kb_public_org_slug_uniq" to table: "knowledge_bases"
CREATE UNIQUE INDEX "idx_kb_public_org_slug_uniq" ON "knowledge_bases" ("org_id", "slug") WHERE (visibility = 'public'::kb_visibility);
-- Create index "idx_kb_search_tsv_public" to table: "knowledge_bases"
CREATE INDEX "idx_kb_search_tsv_public" ON "knowledge_bases" USING GIN ("search_tsv") WHERE (visibility = 'public'::kb_visibility);
-- Create index "idx_kb_source_public_kb_id" to table: "knowledge_bases"
CREATE INDEX "idx_kb_source_public_kb_id" ON "knowledge_bases" ("source_public_kb_id") WHERE (source_public_kb_id IS NOT NULL);
-- Create index "idx_kb_visibility_public" to table: "knowledge_bases"
CREATE INDEX "idx_kb_visibility_public" ON "knowledge_bases" ("visibility") WHERE (visibility = 'public'::kb_visibility);
-- Create index "idx_knowledge_bases_org_id" to table: "knowledge_bases"
CREATE INDEX "idx_knowledge_bases_org_id" ON "knowledge_bases" ("org_id");
-- Create index "idx_knowledge_bases_workspace_id" to table: "knowledge_bases"
CREATE INDEX "idx_knowledge_bases_workspace_id" ON "knowledge_bases" ("workspace_id");
-- Create "airbyte_connectors" table
CREATE TABLE "airbyte_connectors" (
  "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
  "org_id" uuid NOT NULL,
  "knowledge_base_id" uuid NOT NULL,
  "name" character varying(255) NOT NULL,
  "connector_type" character varying(100) NOT NULL,
  "config" jsonb NOT NULL DEFAULT '{}',
  "sync_mode" "sync_mode" NOT NULL DEFAULT 'full_refresh',
  "schedule_cron" character varying(100) NULL,
  "status" "connector_status" NOT NULL DEFAULT 'active',
  "last_sync_at" timestamptz NULL,
  "last_sync_status" character varying(50) NULL,
  "last_sync_records" integer NULL DEFAULT 0,
  "created_by" uuid NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CONSTRAINT "airbyte_connectors_created_by_fkey" FOREIGN KEY ("created_by") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  CONSTRAINT "airbyte_connectors_knowledge_base_id_fkey" FOREIGN KEY ("knowledge_base_id") REFERENCES "knowledge_bases" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "airbyte_connectors_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- Create index "idx_airbyte_connectors_kb" to table: "airbyte_connectors"
CREATE INDEX "idx_airbyte_connectors_kb" ON "airbyte_connectors" ("knowledge_base_id");
-- Create index "idx_airbyte_connectors_org" to table: "airbyte_connectors"
CREATE INDEX "idx_airbyte_connectors_org" ON "airbyte_connectors" ("org_id");
-- Create "airbyte_sync_history" table
CREATE TABLE "airbyte_sync_history" (
  "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
  "connector_id" uuid NOT NULL,
  "org_id" uuid NOT NULL,
  "status" character varying(50) NOT NULL DEFAULT 'running',
  "records_synced" integer NULL DEFAULT 0,
  "records_failed" integer NULL DEFAULT 0,
  "bytes_synced" bigint NULL DEFAULT 0,
  "started_at" timestamptz NOT NULL DEFAULT now(),
  "completed_at" timestamptz NULL,
  "error_message" text NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "airbyte_sync_history_connector_id_fkey" FOREIGN KEY ("connector_id") REFERENCES "airbyte_connectors" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "airbyte_sync_history_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- Create index "idx_sync_history_connector" to table: "airbyte_sync_history"
CREATE INDEX "idx_sync_history_connector" ON "airbyte_sync_history" ("connector_id");
-- Create "api_keys" table
CREATE TABLE "api_keys" (
  "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
  "org_id" uuid NOT NULL,
  "knowledge_base_id" uuid NOT NULL,
  "key_hash" character varying(128) NOT NULL,
  "key_prefix" character varying(20) NOT NULL,
  "name" character varying(255) NOT NULL,
  "allowed_domains" text[] NULL,
  "rate_limit" integer NULL DEFAULT 60,
  "status" "api_key_status" NOT NULL DEFAULT 'active',
  "created_by" uuid NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "expires_at" timestamptz NULL,
  "workspace_id" uuid NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "api_keys_created_by_fkey" FOREIGN KEY ("created_by") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  CONSTRAINT "api_keys_knowledge_base_id_fkey" FOREIGN KEY ("knowledge_base_id") REFERENCES "knowledge_bases" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "api_keys_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "api_keys_workspace_id_fkey" FOREIGN KEY ("workspace_id") REFERENCES "workspaces" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- Create index "idx_api_keys_key_hash" to table: "api_keys"
CREATE INDEX "idx_api_keys_key_hash" ON "api_keys" ("key_hash");
-- Create index "idx_api_keys_knowledge_base_id" to table: "api_keys"
CREATE INDEX "idx_api_keys_knowledge_base_id" ON "api_keys" ("knowledge_base_id");
-- Create index "idx_api_keys_org_id" to table: "api_keys"
CREATE INDEX "idx_api_keys_org_id" ON "api_keys" ("org_id");
-- Create index "idx_api_keys_workspace_id" to table: "api_keys"
CREATE INDEX "idx_api_keys_workspace_id" ON "api_keys" ("workspace_id");
-- Create "catalog_metadata" table
CREATE TABLE "catalog_metadata" (
  "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
  "org_id" uuid NOT NULL,
  "catalog_type" character varying(100) NOT NULL,
  "resource_path" character varying(1000) NOT NULL,
  "labels" jsonb NULL DEFAULT '{}',
  "discovered_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CONSTRAINT "catalog_metadata_org_id_catalog_type_resource_path_key" UNIQUE ("org_id", "catalog_type", "resource_path"),
  CONSTRAINT "catalog_metadata_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- Create "chat_sessions" table
CREATE TABLE "chat_sessions" (
  "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
  "org_id" uuid NOT NULL,
  "knowledge_base_id" uuid NOT NULL,
  "user_id" uuid NULL,
  "session_token" character varying(255) NOT NULL,
  "metadata" jsonb NULL DEFAULT '{}',
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "expires_at" timestamptz NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "chat_sessions_knowledge_base_id_fkey" FOREIGN KEY ("knowledge_base_id") REFERENCES "knowledge_bases" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "chat_sessions_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "chat_sessions_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL
);
-- Create index "idx_chat_sessions_knowledge_base_id" to table: "chat_sessions"
CREATE INDEX "idx_chat_sessions_knowledge_base_id" ON "chat_sessions" ("knowledge_base_id");
-- Create index "idx_chat_sessions_org_id" to table: "chat_sessions"
CREATE INDEX "idx_chat_sessions_org_id" ON "chat_sessions" ("org_id");
-- Create index "idx_chat_sessions_session_token" to table: "chat_sessions"
CREATE INDEX "idx_chat_sessions_session_token" ON "chat_sessions" ("session_token");
-- Create "chat_messages" table
CREATE TABLE "chat_messages" (
  "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
  "session_id" uuid NOT NULL,
  "org_id" uuid NOT NULL,
  "role" "message_role" NOT NULL,
  "content" text NOT NULL,
  "token_count" integer NULL,
  "chunk_ids" uuid[] NULL,
  "model_name" character varying(100) NULL,
  "latency_ms" integer NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CONSTRAINT "chat_messages_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "chat_messages_session_id_fkey" FOREIGN KEY ("session_id") REFERENCES "chat_sessions" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- Create index "idx_chat_messages_org_id" to table: "chat_messages"
CREATE INDEX "idx_chat_messages_org_id" ON "chat_messages" ("org_id");
-- Create index "idx_chat_messages_session_id" to table: "chat_messages"
CREATE INDEX "idx_chat_messages_session_id" ON "chat_messages" ("session_id");
-- Create "documents" table
CREATE TABLE "documents" (
  "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
  "org_id" uuid NOT NULL,
  "knowledge_base_id" uuid NOT NULL,
  "file_name" character varying(500) NOT NULL,
  "file_type" character varying(50) NULL,
  "file_size_bytes" bigint NULL,
  "file_hash" character varying(128) NULL,
  "storage_path" text NULL,
  "processing_status" "processing_status" NOT NULL DEFAULT 'queued',
  "processing_error" text NULL,
  "title" character varying(500) NULL,
  "page_count" integer NULL,
  "metadata" jsonb NULL DEFAULT '{}',
  "uploaded_by" uuid NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CONSTRAINT "documents_knowledge_base_id_fkey" FOREIGN KEY ("knowledge_base_id") REFERENCES "knowledge_bases" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "documents_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "documents_uploaded_by_fkey" FOREIGN KEY ("uploaded_by") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL
);
-- Create index "idx_documents_file_hash" to table: "documents"
CREATE INDEX "idx_documents_file_hash" ON "documents" ("file_hash");
-- Create index "idx_documents_knowledge_base_id" to table: "documents"
CREATE INDEX "idx_documents_knowledge_base_id" ON "documents" ("knowledge_base_id");
-- Create index "idx_documents_org_id" to table: "documents"
CREATE INDEX "idx_documents_org_id" ON "documents" ("org_id");
-- Create index "idx_documents_processing_status" to table: "documents"
CREATE INDEX "idx_documents_processing_status" ON "documents" ("processing_status");
-- Create "sources" table
CREATE TABLE "sources" (
  "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
  "org_id" uuid NOT NULL,
  "knowledge_base_id" uuid NOT NULL,
  "source_type" "source_type" NOT NULL,
  "url" text NOT NULL,
  "crawl_depth" integer NULL DEFAULT 1,
  "crawl_frequency" "crawl_frequency" NOT NULL DEFAULT 'manual',
  "processing_status" "processing_status" NOT NULL DEFAULT 'queued',
  "processing_error" text NULL,
  "title" character varying(500) NULL,
  "pages_crawled" integer NULL DEFAULT 0,
  "metadata" jsonb NULL DEFAULT '{}',
  "created_by" uuid NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CONSTRAINT "sources_created_by_fkey" FOREIGN KEY ("created_by") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  CONSTRAINT "sources_knowledge_base_id_fkey" FOREIGN KEY ("knowledge_base_id") REFERENCES "knowledge_bases" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "sources_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- Create index "idx_sources_knowledge_base_id" to table: "sources"
CREATE INDEX "idx_sources_knowledge_base_id" ON "sources" ("knowledge_base_id");
-- Create index "idx_sources_org_id" to table: "sources"
CREATE INDEX "idx_sources_org_id" ON "sources" ("org_id");
-- Create index "idx_sources_processing_status" to table: "sources"
CREATE INDEX "idx_sources_processing_status" ON "sources" ("processing_status");
-- Create "chunks" table
CREATE TABLE "chunks" (
  "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
  "org_id" uuid NOT NULL,
  "knowledge_base_id" uuid NOT NULL,
  "document_id" uuid NULL,
  "source_id" uuid NULL,
  "content" text NOT NULL,
  "chunk_index" integer NOT NULL,
  "token_count" integer NULL,
  "page_number" integer NULL,
  "heading" character varying(500) NULL,
  "chunk_type" "chunk_type" NOT NULL DEFAULT 'text',
  "metadata" jsonb NULL DEFAULT '{}',
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "chunk_hash" character varying(64) NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "chunks_document_id_fkey" FOREIGN KEY ("document_id") REFERENCES "documents" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "chunks_knowledge_base_id_fkey" FOREIGN KEY ("knowledge_base_id") REFERENCES "knowledge_bases" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "chunks_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "chunks_source_id_fkey" FOREIGN KEY ("source_id") REFERENCES "sources" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "chunks_check" CHECK ((document_id IS NOT NULL) OR (source_id IS NOT NULL))
);
