CREATE TABLE "conversation_sessions" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "org_id" uuid NOT NULL,
  "kb_id" uuid NOT NULL,
  "user_id" text NOT NULL,
  "channel" text NOT NULL,
