  CONSTRAINT "chk_conversation_sessions_messages_is_array" CHECK (jsonb_typeof(messages) = 'array'::text),
  CONSTRAINT "chk_conversation_sessions_times" CHECK ((ended_at IS NULL) OR (ended_at >= started_at)),
