-- Create "stranger_users" table
CREATE TABLE "stranger_users" (
  "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
  "org_id" uuid NOT NULL,
  "session_id" character varying(255) NOT NULL,
  "ip_address" inet NULL,
  "user_agent" text NULL,
  "status" "stranger_status" NOT NULL DEFAULT 'active',
  "block_reason" text NULL,
  "message_count" integer NOT NULL DEFAULT 0,
  "rate_limit_rpm" integer NULL,
  "last_active_at" timestamptz NOT NULL DEFAULT now(),
  "blocked_at" timestamptz NULL,
  "blocked_by" uuid NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CONSTRAINT "stranger_users_org_id_session_id_key" UNIQUE ("org_id", "session_id"),
  CONSTRAINT "stranger_users_blocked_by_fkey" FOREIGN KEY ("blocked_by") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  CONSTRAINT "stranger_users_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "stranger_users_rate_limit_rpm_check" CHECK ((rate_limit_rpm IS NULL) OR (rate_limit_rpm > 0))
);
