-- Create index "idx_stranger_users_org_status" to table: "stranger_users"
CREATE INDEX "idx_stranger_users_org_status" ON "stranger_users" ("org_id", "status");
-- Create "subscriptions" table
CREATE TABLE "subscriptions" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "org_id" uuid NOT NULL,
  "plan_id" text NOT NULL,
  "status" text NOT NULL DEFAULT 'active',
  "hyperswitch_subscription_id" text NULL,
  "current_period_start" timestamptz NOT NULL DEFAULT now(),
  "current_period_end" timestamptz NOT NULL DEFAULT (now() + '1 mon'::interval),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "seat_count" integer NOT NULL DEFAULT 1,
  "billing_cycle" text NOT NULL DEFAULT 'monthly',
  "trial_ends_at" timestamptz NULL,
  "grace_period_ends_at" timestamptz NULL,
  "refund_id" text NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "subscriptions_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "subscriptions_billing_cycle_check" CHECK (billing_cycle = ANY (ARRAY['monthly'::text, 'annual'::text])),
  CONSTRAINT "subscriptions_status_check" CHECK (status = ANY (ARRAY['active'::text, 'canceled'::text, 'past_due'::text, 'trialing'::text, 'paused'::text, 'expired'::text]))
);
-- Create index "idx_subscriptions_hyperswitch_id" to table: "subscriptions"
CREATE INDEX "idx_subscriptions_hyperswitch_id" ON "subscriptions" ("hyperswitch_subscription_id") WHERE (hyperswitch_subscription_id IS NOT NULL);
-- Create index "idx_subscriptions_org_active" to table: "subscriptions"
CREATE UNIQUE INDEX "idx_subscriptions_org_active" ON "subscriptions" ("org_id") WHERE (status = ANY (ARRAY['active'::text, 'trialing'::text, 'past_due'::text]));
