-- Create "voice_sessions" table
CREATE TABLE "voice_sessions" (
  "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
  "org_id" uuid NOT NULL,
  "user_id" uuid NULL,
  "stranger_id" uuid NULL,
  "livekit_room" character varying(255) NOT NULL,
  "state" "voice_session_state" NOT NULL DEFAULT 'created',
  "started_at" timestamptz NULL,
  "ended_at" timestamptz NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "call_duration_seconds" integer NULL GENERATED ALWAYS AS (
CASE
    WHEN ((started_at IS NOT NULL) AND (ended_at IS NOT NULL)) THEN (EXTRACT(epoch FROM (ended_at - started_at)))::integer
    ELSE NULL::integer
END) STORED,
  PRIMARY KEY ("id"),
  CONSTRAINT "voice_sessions_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "voice_sessions_stranger_id_fkey" FOREIGN KEY ("stranger_id") REFERENCES "stranger_users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  CONSTRAINT "voice_sessions_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  CONSTRAINT "chk_voice_session_actor" CHECK (((user_id IS NOT NULL) AND (stranger_id IS NULL)) OR ((user_id IS NULL) AND (stranger_id IS NOT NULL)) OR ((user_id IS NULL) AND (stranger_id IS NULL))),
  CONSTRAINT "chk_voice_session_times" CHECK ((started_at IS NULL) OR (ended_at IS NULL) OR (ended_at >= started_at))
);
-- Create index "idx_voice_sessions_org" to table: "voice_sessions"
CREATE INDEX "idx_voice_sessions_org" ON "voice_sessions" ("org_id");
-- Create index "idx_voice_sessions_org_created" to table: "voice_sessions"
CREATE INDEX "idx_voice_sessions_org_created" ON "voice_sessions" ("org_id", "created_at" DESC);
-- Create index "idx_voice_sessions_org_state" to table: "voice_sessions"
CREATE INDEX "idx_voice_sessions_org_state" ON "voice_sessions" ("org_id", "state");
-- Create index "idx_voice_sessions_stranger" to table: "voice_sessions"
CREATE INDEX "idx_voice_sessions_stranger" ON "voice_sessions" ("org_id", "stranger_id") WHERE (stranger_id IS NOT NULL);
-- Create index "idx_voice_sessions_user" to table: "voice_sessions"
CREATE INDEX "idx_voice_sessions_user" ON "voice_sessions" ("org_id", "user_id") WHERE (user_id IS NOT NULL);
