  CONSTRAINT "voice_turns_session_id_fkey" FOREIGN KEY ("session_id") REFERENCES "voice_sessions" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "chk_voice_turn_times" CHECK ((ended_at IS NULL) OR (ended_at >= started_at))
);
