  "next_retry_at" timestamptz NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "completed_at" timestamptz NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fk_webhook_deliveries_config" FOREIGN KEY ("webhook_id", "org_id") REFERENCES "webhook_configs" ("id", "org_id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "webhook_deliveries_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
