CREATE INDEX "idx_webhook_deliveries_retry" ON "webhook_deliveries" ("next_retry_at") WHERE ((status)::text = 'pending'::text);
-- Create index "idx_webhook_deliveries_status" to table: "webhook_deliveries"
CREATE INDEX "idx_webhook_deliveries_status" ON "webhook_deliveries" ("webhook_id", "status");
