-- Create "whatsapp_calls" table
CREATE TABLE "whatsapp_calls" (
  "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
  "org_id" uuid NOT NULL,
  "call_id" character varying(128) NOT NULL,
  "phone_number_id" uuid NOT NULL,
  "direction" "whatsapp_call_direction" NOT NULL,
  "state" "whatsapp_call_state" NOT NULL DEFAULT 'ringing',
  "caller" character varying(20) NOT NULL,
  "callee" character varying(20) NOT NULL,
  "started_at" timestamptz NULL,
  "ended_at" timestamptz NULL,
  "duration_seconds" integer NULL GENERATED ALWAYS AS (
CASE
    WHEN ((started_at IS NOT NULL) AND (ended_at IS NOT NULL)) THEN (EXTRACT(epoch FROM (ended_at - started_at)))::integer
    ELSE NULL::integer
END) STORED,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_whatsapp_call_id" UNIQUE ("call_id"),
  CONSTRAINT "whatsapp_calls_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "whatsapp_calls_phone_number_id_fkey" FOREIGN KEY ("phone_number_id") REFERENCES "whatsapp_phone_numbers" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "chk_whatsapp_call_times" CHECK ((started_at IS NULL) OR (ended_at IS NULL) OR (ended_at >= started_at))
);
